from itertools import permutations

people = ['Casey', 'Devon', 'Parker', 'Sawyer']
colors = ['blue', 'green', 'orange', 'yellow']
pets = ['bird', 'cat', 'fish', 'rabbit']
drinks = ['cocoa', 'coffee', 'milk', 'tea']

def get_position(assignment, attribute):
    for pos in range(1, 5):
        person, color, pet, drink = assignment[pos]
        if person == attribute or color == attribute or pet == attribute or drink == attribute:
            return pos
    return None

def check_clues(assignment):
    # Clue 1: The fish owner lives next to Parker
    if abs(get_position(assignment, 'fish') - get_position(assignment, 'Parker')) != 1:
        return False

    # Clue 2: Parker lives next to the person who drinks coffee
    if abs(get_position(assignment, 'Parker') - get_position(assignment, 'coffee')) != 1:
        return False

    # Clue 3: Devon lives next to the person in the green house
    if abs(get_position(assignment, 'Devon') - get_position(assignment, 'green')) != 1:
        return False

    # Clue 4: Sawyer is not the person who drinks milk
    sawyer_pos = get_position(assignment, 'Sawyer')
    if assignment[sawyer_pos][3] == 'milk':
        return False

    # Clue 5: The person who drinks cocoa lives next to the person in the orange house
    if abs(get_position(assignment, 'cocoa') - get_position(assignment, 'orange')) != 1:
        return False

    # Clue 6: The rabbit owner lives immediately to the left of the person who drinks coffee
    if get_position(assignment, 'coffee') - get_position(assignment, 'rabbit') != 1:
        return False

    # Clue 7: Parker lives immediately to the left of the person who drinks cocoa
    if get_position(assignment, 'cocoa') - get_position(assignment, 'Parker') != 1:
        return False

    # Clue 8: The person in the orange house is not the person who drinks milk
    orange_pos = get_position(assignment, 'orange')
    if assignment[orange_pos][3] == 'milk':
        return False

    # Clue 9: The person who drinks milk lives immediately to the left of the bird owner
    if get_position(assignment, 'bird') - get_position(assignment, 'milk') != 1:
        return False

    # Clue 10: The rabbit owner lives immediately to the left of the person in the blue house
    if get_position(assignment, 'blue') - get_position(assignment, 'rabbit') != 1:
        return False

    return True

def solve():
    for people_perm in permutations(people):
        for colors_perm in permutations(colors):
            for pets_perm in permutations(pets):
                for drinks_perm in permutations(drinks):
                    assignment = {
                        1: (people_perm[0], colors_perm[0], pets_perm[0], drinks_perm[0]),
                        2: (people_perm[1], colors_perm[1], pets_perm[1], drinks_perm[1]),
                        3: (people_perm[2], colors_perm[2], pets_perm[2], drinks_perm[2]),
                        4: (people_perm[3], colors_perm[3], pets_perm[3], drinks_perm[3]),
                    }

                    if check_clues(assignment):
                        for pos in range(1, 5):
                            if assignment[pos][2] == 'fish':
                                print(f"ANSWER: {assignment[pos][0]}")
                                return

solve()
